import { createStore } from 'zustand/vanilla';

if (!window.__GLOBAL_DATA_STORE__) {
  window.__GLOBAL_DATA_STORE__ = createStore((set, get) => ({
    sites: [],
    categories: [],
    watersheds: [],
    waterbodies: [],
    organizations: [],
    states: [],
    counties: [],
    towns: [],
    boudaries: {},
    query: {},
    drawnBoundaryType: undefined,
    drawnBoundaryId: undefined,
    kdIndex: [],
    points: [],

    isBoundariesLoaded: false,
    lang: 'en',
    zeroResultsShown: false,
    initialized: false,
    accessibility: false,
    userLocation: undefined,
    mapStyle: 'mapbox://styles/rodonnell-ctriver/cme050tqw018g01qpa23h8jj3',

    setKdIndex: (kdIndex) => set(() => ({ kdIndex })),
    setPoints: (points) => set(() => ({ points })),
    setUserLocation: (userLocation) => set(() => ({ userLocation })),
    setSites: (sites) => set(() => ({ sites })),
    setCategories: (categories) => set(() => ({ categories })),
    setQuery: (query) => set(() => ({ query })),
    setStates: (states) => set(() => ({ states })),
    setCounties: (counties) => set(() => ({ counties })),
    setTowns: (towns) => set(() => ({ towns })),
    setWaterSheds: (watersheds) => set(() => ({ watersheds })),
    setWaterBodies: (waterbodies) => set(() => ({ waterbodies })),
    setOrganizations: (organizations) => set(() => ({ organizations })),
    setBoundaries: (boudaries) => set(() => ({ boudaries })),
    setIsBoundariesLoaded: (isBoundariesLoaded) => set(() => ({ isBoundariesLoaded })),
    setLang: (lang) => set(() => ({ lang })),
    setMapStyle: (mapStyle) => set(() => ({ mapStyle })),
    setInitialized: (initialized) => set(() => ({ initialized })),
    setAccessibility: (accessibility) => set(() => ({ accessibility })),
    setZeroResultsShown: (zeroResultsShown) => set(() => ({ zeroResultsShown })),
    setDrawnBoundaryType: (drawnBoundaryType) => set(() => ({ drawnBoundaryType })),
    setDrawnBoundaryId: (drawnBoundaryId) => set(() => ({ drawnBoundaryId })),
    toggleAccessibility: () => set((state) => ({ accessibility: !state.accessibility })),
    getSites: () => get().sites,
    getCategories: () => get().categories,
    getWaterSheds: () => get().watersheds,
    getWaterBodies: () => get().waterbodies,
    getStates: () => get().states,
    getCounties: () => get().counties,
    getTowns: () => get().towns,
    getOrganizations: () => get().organizations,
    getBoundaries: () => get().boudaries,
    getIsBoundariesLoaded: () => get().isBoundariesLoaded,
    getLang: () => get().lang,
    getQuery: () => get().query,
    getZeroResultsShown: () => get().zeroResultsShown,
    getInitialized: () => get().initialized,
    getAccessibility: () => get().accessibility,
    getDrawnBoundaryType: () => get().drawnBoundaryType,
    getDrawnBoundaryId: () => get().drawnBoundaryId,
    getKdIndex: () => get().kdIndex,
    getPoints: () => get().points,
    getUserLocation: () => get().userLocation,
    getMapStyle: () => get().mapStyle,
  }));
}

export const useDataStore = window.__GLOBAL_DATA_STORE__;
